contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public {
        // Owner is this test contract (deployer of fresh c). Give it supply by minting.
        c.mintToken(address(this), 1000);
        require(c.balanceOf(address(this)) >= burnAmount, "insufficient balance for burn");
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        bool reverted;
        c.burn(burnAmount);
        reverted = false;
        assert(!reverted && c.balanceOf(address(this)) == balBefore - burnAmount && c.totalSupply() == supplyBefore - burnAmount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, address frozenTarget, uint256 mintAmt, uint256 sendAmt) public {
        require(to != address(this));
        require(frozenTarget != to);
        require(frozenTarget != address(this));
        require(mintAmt > 0);
        require(sendAmt > 0 && sendAmt <= mintAmt);

        uint256 ts0 = c.totalSupply();
        c.mintToken(address(this), mintAmt);

        c.freezeAccount(to, false);
        c.freezeAccount(frozenTarget, true);

        bool revertedFrozen;
        try c.transfer(frozenTarget, 1) { revertedFrozen = false; } catch { revertedFrozen = true; }

        uint256 toBalBefore = c.balanceOf(to);
        uint256 selfBalBefore = c.balanceOf(address(this));
        bool ok;
        try c.transfer(to, sendAmt) { ok = true; } catch { ok = false; }

        uint256 toBalAfter = c.balanceOf(to);
        uint256 selfBalAfter = c.balanceOf(address(this));

        assert(
            revertedFrozen
            && ok
            && toBalAfter == toBalBefore + sendAmt
            && selfBalAfter + sendAmt == selfBalBefore
            && c.totalSupply() == ts0 + mintAmt
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint256 excessAmount, uint256 okAmount) public {
        require(recipient != address(0));
        require(okAmount > 0 && okAmount <= c.balanceOf(address(this)) / 2);
        require(excessAmount > c.balanceOf(address(this)));

        uint256 supplyBefore = c.totalSupply();
        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, excessAmount) { reverted = false; } catch { reverted = true; }

        assert(reverted
            && c.totalSupply() == supplyBefore
            && c.balanceOf(address(this)) == senderBefore
            && c.balanceOf(recipient) == recipBefore);

        bool ok = c.transfer(recipient, okAmount);

        assert(ok
            && c.totalSupply() == supplyBefore
            && c.balanceOf(address(this)) + okAmount == senderBefore
            && c.balanceOf(recipient) == recipBefore + okAmount);
    }
    receive() external payable {}
}

