contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 supply, uint256 burnAmt) public {
        require(burnAmt <= supply);
        // owner (this contract) holds supply tokens from construction
        c.freezeAccount(address(this), true);
        uint256 tsBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        bool ok;
        c.burn(burnAmt);
        ok = true;
        assert(ok && c.totalSupply() == tsBefore - burnAmt && c.balanceOf(address(this)) == balBefore - burnAmt);
    }
